-- Mission 05: forward-only result authority. Generated by Supabase CLI 2.122.0.
-- Query/column inventory: docs/plans/2026-10-24-mission05-security-remediation.md.
-- No data changes, SELECT/DELETE changes, view recreation or service-role changes.
-- Apply only through a separately approved release. Do not restore client writes
-- as a rollback: that reintroduces forged scores and AI provenance.
-- Supabase CLI 2.122.0 owns the transaction: this ordinary migration and its
-- history insert execute in one batch. Atomicity does not make a top-level
-- LOCK TABLE eligible for CheckTransactionBlock; acquire locks inside the DO.
-- Do not execute statement-by-statement or enable transaction=false.
-- Retained statement-timeout hint can warn outside an explicit transaction
-- block. Its protocol-message timing is not a guaranteed 15s file deadline.
SET LOCAL statement_timeout = '15s';

DO $migration$
DECLARE
  targets oid[];
  public_view oid;
  lock_timeout_value interval;
  preserved_policies jsonb;
  preserved_access jsonb;
  preserved_view text;
  current_snapshot jsonb;
  relation record;
  client_role text;
  column_row record;
BEGIN
  PERFORM pg_catalog.set_config('lock_timeout', '3s', true);
  lock_timeout_value := pg_catalog.current_setting('lock_timeout')::interval;
  IF lock_timeout_value IS NULL OR lock_timeout_value <= interval '0 seconds'
    OR lock_timeout_value > interval '3 seconds' THEN
    RAISE EXCEPTION 'Mission05: bounded lock timeout unavailable';
  END IF;
  LOCK TABLE public.challenge_submissions, public.team_ppt_evaluations,
    public.user_pitch_evaluations IN ACCESS EXCLUSIVE MODE;
  targets := ARRAY['public.challenge_submissions'::regclass::oid,
    'public.team_ppt_evaluations'::regclass::oid, 'public.user_pitch_evaluations'::regclass::oid];
  public_view := 'public.team_ppt_evaluations_public'::regclass::oid;

  IF current_user <> 'postgres' AND NOT (SELECT rolsuper FROM pg_roles WHERE rolname = current_user) THEN
    RAISE EXCEPTION 'Mission05: migration must execute as the verified object owner';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_auth_members WHERE member IN
    ('anon'::regrole, 'authenticated'::regrole, 'service_role'::regrole)) THEN
    RAISE EXCEPTION 'Mission05: unexpected inherited role privileges; review before retry';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_class WHERE oid = ANY(targets)
    AND (relkind <> 'r' OR NOT relrowsecurity OR pg_get_userbyid(relowner) <> 'postgres')) OR
    NOT EXISTS (SELECT 1 FROM pg_class WHERE oid = public_view AND relkind = 'v'
      AND pg_get_userbyid(relowner) = 'postgres'
      AND 'security_invoker=true' = ANY(coalesce(reloptions, ARRAY[]::text[]))) THEN
    RAISE EXCEPTION 'Mission05: ownership/RLS/invoker-view drift';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_class c CROSS JOIN LATERAL
    aclexplode(coalesce(c.relacl, acldefault('r', c.relowner))) a
    WHERE (c.oid = ANY(targets) OR c.oid = public_view) AND a.grantor <> c.relowner) THEN
    RAISE EXCEPTION 'Mission05: unexpected privilege grantor';
  END IF;
  -- Only the known team_id column grant is compatible with this reviewed baseline.
  IF EXISTS (SELECT 1 FROM pg_attribute a CROSS JOIN LATERAL aclexplode(a.attacl) g
    WHERE (a.attrelid = ANY(targets) OR a.attrelid = public_view)
      AND g.privilege_type IN ('INSERT', 'UPDATE') AND NOT
        (a.attrelid = 'public.user_pitch_evaluations'::regclass AND a.attname = 'team_id'
          AND g.grantee = 'authenticated'::regrole AND g.grantor = 'postgres'::regrole
          AND g.privilege_type = 'UPDATE' AND NOT g.is_grantable)) THEN
    RAISE EXCEPTION 'Mission05: unexpected column writer';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_policy p WHERE p.polrelid = ANY(targets)
    AND p.polcmd NOT IN ('r', 'd') AND NOT (
      (p.polrelid = 'public.challenge_submissions'::regclass AND p.polcmd = 'a'
        AND p.polname = 'Authenticated users can submit to challenges') OR
      (p.polrelid = 'public.team_ppt_evaluations'::regclass AND
        ((p.polcmd = 'a' AND p.polname IN ('Allow team members to insert team_ppt_evaluations', 'Allow team members to insert pitch evaluations')) OR
         (p.polcmd = 'w' AND p.polname = 'Allow team members to update team_ppt_evaluations'))) OR
      (p.polrelid = 'public.user_pitch_evaluations'::regclass AND
        ((p.polcmd = 'a' AND p.polname = 'Users can insert own pitch evaluations') OR
         (p.polcmd = 'w' AND p.polname = 'Users can update own pitch evaluations'))))) THEN
    RAISE EXCEPTION 'Mission05: unexpected write/ALL policy';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND p.prokind IN ('f', 'p')
      AND p.prosrc ~ '(challenge_submissions|team_ppt_evaluations|user_pitch_evaluations)') OR
    EXISTS (SELECT 1 FROM pg_views v WHERE v.schemaname NOT IN ('pg_catalog', 'information_schema')
      AND v.definition ~ '(challenge_submissions|team_ppt_evaluations|user_pitch_evaluations)'
      AND NOT (v.schemaname = 'public' AND v.viewname = 'team_ppt_evaluations_public')) OR
    EXISTS (SELECT 1 FROM pg_rewrite WHERE ev_class = ANY(targets) AND rulename <> '_RETURN') THEN
    RAISE EXCEPTION 'Mission05: unexpected function/view/rule dependency';
  END IF;

  SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.oid), '[]') INTO preserved_policies
    FROM pg_policy p WHERE p.polrelid = ANY(targets) AND p.polcmd IN ('r', 'd');
  SELECT jsonb_agg(jsonb_build_array(c.oid, a.grantor, a.grantee, a.privilege_type, a.is_grantable)
    ORDER BY c.oid, a.grantor, a.grantee, a.privilege_type) INTO preserved_access
    FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl, acldefault('r', c.relowner))) a
    WHERE (c.oid = ANY(targets) OR c.oid = public_view) AND a.privilege_type IN ('SELECT', 'DELETE');
  preserved_view := pg_get_viewdef(public_view, true);

  REVOKE INSERT, UPDATE, TRUNCATE, TRIGGER ON TABLE public.challenge_submissions,
    public.team_ppt_evaluations, public.user_pitch_evaluations FROM PUBLIC, anon, authenticated;
  REVOKE UPDATE (team_id) ON TABLE public.user_pitch_evaluations FROM PUBLIC, anon, authenticated;
  REVOKE INSERT, UPDATE ON TABLE public.team_ppt_evaluations_public FROM PUBLIC, anon, authenticated;
  DROP POLICY IF EXISTS "Authenticated users can submit to challenges" ON public.challenge_submissions;
  DROP POLICY IF EXISTS "Allow team members to insert team_ppt_evaluations" ON public.team_ppt_evaluations;
  DROP POLICY IF EXISTS "Allow team members to insert pitch evaluations" ON public.team_ppt_evaluations;
  DROP POLICY IF EXISTS "Allow team members to update team_ppt_evaluations" ON public.team_ppt_evaluations;
  DROP POLICY IF EXISTS "Users can insert own pitch evaluations" ON public.user_pitch_evaluations;
  DROP POLICY IF EXISTS "Users can update own pitch evaluations" ON public.user_pitch_evaluations;

  FOR relation IN SELECT oid FROM pg_class WHERE oid = ANY(targets) OR oid = public_view LOOP
    FOREACH client_role IN ARRAY ARRAY['anon', 'authenticated'] LOOP
      IF has_table_privilege(client_role, relation.oid, 'INSERT') OR has_table_privilege(client_role, relation.oid, 'UPDATE') THEN
        RAISE EXCEPTION 'Mission05: effective client table writer remains';
      END IF;
      FOR column_row IN SELECT attnum FROM pg_attribute WHERE attrelid = relation.oid AND attnum > 0 AND NOT attisdropped LOOP
        IF has_column_privilege(client_role, relation.oid, column_row.attnum, 'INSERT') OR
          has_column_privilege(client_role, relation.oid, column_row.attnum, 'UPDATE') THEN
          RAISE EXCEPTION 'Mission05: effective client column writer remains';
        END IF;
      END LOOP;
      IF relation.oid = ANY(targets) AND (has_table_privilege(client_role, relation.oid, 'TRUNCATE') OR
        has_table_privilege(client_role, relation.oid, 'TRIGGER')) THEN
        RAISE EXCEPTION 'Mission05: destructive client privilege remains';
      END IF;
    END LOOP;
    IF NOT has_table_privilege('service_role', relation.oid, 'SELECT') OR
      NOT has_table_privilege('service_role', relation.oid, 'INSERT') OR
      NOT has_table_privilege('service_role', relation.oid, 'UPDATE') OR
      NOT has_table_privilege('service_role', relation.oid, 'DELETE') THEN
      RAISE EXCEPTION 'Mission05: service-role access unavailable';
    END IF;
  END LOOP;
  IF NOT (SELECT rolbypassrls FROM pg_roles WHERE rolname = 'service_role') OR
    EXISTS (SELECT 1 FROM pg_policy WHERE polrelid = ANY(targets) AND polcmd NOT IN ('r', 'd')) THEN
    RAISE EXCEPTION 'Mission05: result-authority postcondition failed';
  END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.oid), '[]') INTO current_snapshot
    FROM pg_policy p WHERE p.polrelid = ANY(targets) AND p.polcmd IN ('r', 'd');
  IF current_snapshot IS DISTINCT FROM preserved_policies THEN
    RAISE EXCEPTION 'Mission05: SELECT/DELETE policy changed';
  END IF;
  SELECT jsonb_agg(jsonb_build_array(c.oid, a.grantor, a.grantee, a.privilege_type, a.is_grantable)
    ORDER BY c.oid, a.grantor, a.grantee, a.privilege_type) INTO current_snapshot
    FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl, acldefault('r', c.relowner))) a
    WHERE (c.oid = ANY(targets) OR c.oid = public_view) AND a.privilege_type IN ('SELECT', 'DELETE');
  IF current_snapshot IS DISTINCT FROM preserved_access OR pg_get_viewdef(public_view, true) IS DISTINCT FROM preserved_view THEN
    RAISE EXCEPTION 'Mission05: read/deletion access or view definition changed';
  END IF;
END;
$migration$;
